	/// <summary>
/// This is a contract class
/// CB387_DallasPickListRegistration
/// </summary>
[DataContractAttribute]
final class METDallasPicklistRegContract
{
    int         tasksNumber;
    str         packedQuery;
    container   conOrdTrans;
    boolean     processExtInvSo;
			
}

Method.Source:
/// <summary>
/// This method takes task numbers as input from UI and provides the same as output if exists
/// </summary>
/// <param name = "_tasksNumber">TaskNumber</param>
/// <returns>TaskNumber</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute('@MET:CustCreditLimitTasks'),
    SysOperationDisplayOrderAttribute('1')
]
public int parmParallelTasksNumber(int _tasksNumber = tasksNumber)
{
    tasksNumber = _tasksNumber;
    return tasksNumber;
}

/// <summary>
/// Gets or sets the flag that determines whether externally invoiced sales orders should be processed.
/// </summary>
/// <param name="_processExtInvSo">
/// Boolean value passed in from the UI.
/// True = process externally invoiced sales orders,
/// False = skip them.
/// </param>
/// <returns>
/// The current value of the processExtInvSo flag.
/// </returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute('@MET:ProcessExtInvSO'),
    SysOperationDisplayOrderAttribute('2')
]
public boolean parmProcessExtInvSo(boolean _processExtInvSo = processExtInvSo)
{
    processExtInvSo = _processExtInvSo;
    return processExtInvSo;
}

    /// <summary>
    /// Gets/set packed query.
    /// </summary>
    /// <param name = "_packedQuery">Packed query.</param>
    /// <returns>Packed query.</returns>
    [
        DataMemberAttribute,
        AifQueryTypeAttribute('_packedQuery', queryStr(METWMSOrderTrans))
    ]
    public str parmPackedQuery(str _packedQuery = packedQuery)
    {
        packedQuery = _packedQuery;

        return packedQuery;
    }

/// <summary>
/// This is a parm method
/// </summary>
/// <param name = "_conOrdTrans">OrdTrans</param>
/// <returns>Container</returns>
[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public container parmConOrderTrans(container _conOrdTrans = conOrdTrans)
{
    conOrdTrans = _conOrdTrans;
    return conOrdTrans;
}

/// <summary>
/// Method to get query object from packedQuery
/// </summary>
/// <returns><c>Query</c> object from packedQuery</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}
